{"version":3,"sources":["src/math.ts","src/main.ts"],"sourcesContent":["export function checkPositive(value: number): number {
  if (value <= 0) {
    throw new RangeError('value must be positive: ' + value);
  }
  return value;
}

export class Accumulator {
  total = 0;
  add(value: number): void {
    this.total += checkPositive(value);
  }
}
","import { Accumulator } from './math';

function sumAll(values: number[]): number {
  const acc = new Accumulator();
  for (const v of values) {
    acc.add(v);
  }
  return acc.total;
}

export function run(): number {
  return sumAll([3, 5, -2, 7]);
}

run();
